import {esc} from './models.js';
export function equationHTML(lesson){const guide=lesson.equationGuide;return `<div class="equation">${esc(lesson.equation)}</div>${guide?`<p class="equation-meaning">${esc(guide.meaning)}</p><p class="terms">${esc(lesson.terms)}</p><details class="symbol-guide"><summary>What each symbol means</summary><dl>${guide.symbols.map(s=>`<div><dt><code>${esc(s.symbol)}</code> ${esc(s.name)}</dt><dd>${esc(s.description)} <span class="symbol-unit">Unit: ${esc(s.unit)}.</span></dd></div>`).join('')}</dl></details>`:`<p class="terms">${esc(lesson.terms)}</p>`}`;}
export function glossaryHTML(lesson){if(!lesson.glossary?.length)return '';return `<details class="lesson-glossary"><summary>Glossary · plain meanings for ${lesson.glossary.length} ${lesson.glossary.length===1?'word':'words'}</summary><dl>${lesson.glossary.map(g=>`<div><dt>${esc(g.term)}</dt><dd>${esc(g.definition)}${g.example?`<span class="glossary-example">${esc(g.example)}</span>`:''}</dd></div>`).join('')}</dl></details>`;}
export function prerequisitesHTML(lesson,courseId,courses){const ids=lesson.prerequisiteIds??[];if(!ids.length)return '';return `<p class="lesson-preparation"><strong>Builds on:</strong> ${ids.map(id=>{const [c,l]=id.includes('/')?id.split('/'):[courseId,id];const target=courses.get(c)?.lessons.find(item=>item.id===l);return target?`<a href="#learn/${esc(c)}/${esc(l)}">${esc(target.title)}</a>`:esc(id);}).join(' · ')}. You can revisit these freely.</p>`;}
